const youngMB = 4;
const allocMBs = 200;
// a scavenge happens each time we allocate youngMB worth of objects
const scavengesPerSec = allocMBs / youngMB;
const gapMs = 1000 / scavengesPerSec;
console.log(`${scavengesPerSec} scavenges/sec`);
console.log(`${gapMs} ms between scavenges`);

function frame(particles) {
  for (const p of particles) {
    const velocity = { x: p.vx, y: p.vy }; // new object every particle every frame
    const next = { x: p.x + velocity.x, y: p.y + velocity.y };
    p.x = next.x; p.y = next.y;
  }
}
